import{_ as e,o,c as d,a2 as r}from"./chunks/framework.yO0biSGH.js";const h=JSON.parse('{"title":"26 学习路线：七天速通，然后靠项目补细节","description":"","frontmatter":{"title":"26 学习路线：七天速通，然后靠项目补细节"},"headers":[],"relativePath":"handbook/26-route.md","filePath":"handbook/26-route.md","lastUpdated":1793969410000}'),c={name:"handbook/26-route.md"};function a(i,t,s,n,l,u){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="_26-学习路线-七天速通-然后靠项目补细节" tabindex="-1">26 学习路线：七天速通，然后靠项目补细节 <a class="header-anchor" href="#_26-学习路线-七天速通-然后靠项目补细节" aria-label="Permalink to &quot;26 学习路线：七天速通，然后靠项目补细节&quot;">​</a></h1><blockquote><p>详细程度：路线 · 约 7 分钟 材料：本手册 01 到 25 节 前置：任意一门主流语言的后端经验</p></blockquote><h2 id="这套手册怎么用" tabindex="-1">这套手册怎么用 <a class="header-anchor" href="#这套手册怎么用" aria-label="Permalink to &quot;这套手册怎么用&quot;">​</a></h2><p>手册 01 到 27 节的头部时长加起来是 1877 分钟，约 31.3 小时；它只用于估计阅读量，不包括全部练习与项目时间。目标不是背结论，而是建立 Go 与后端工程的知识地图。读到代码时，先判断它是完整程序、沿用前文的片段，还是刻意展示错误的例子；对可运行的完整例子，先猜行为再运行，对照解释找出理解偏差。细节有三层可以回查：</p><ol><li>每节正文里吸收不了的细节收在&quot;想深入:正文之外的干货&quot;小节；再往外是&quot;想深入去哪查&quot;，指向 <code>work/digest/</code> 的知识点摘要（带页码，一般不用翻原材料原文）。</li><li>旧长版 <code>notes/</code>，每个主题有更长的讲解、完整练习和复盘记录。</li><li><code>exercises/</code> 的练习包是已经写好的参考实现，测试本来就是绿的。过关的做法是把实现删掉自己重写，直到测试全绿，或者故意改坏一处再修回。</li></ol><p>读完一节后做两件事：先不看答案回答&quot;判断题&quot;，再选一个练习跑一遍。答不出来的，回去重读那一节的对应范式，而不是去翻细节。</p><h2 id="七天路线" tabindex="-1">七天路线 <a class="header-anchor" href="#七天路线" aria-label="Permalink to &quot;七天路线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>天</th><th>节</th><th>目标</th><th>练习（约 N 分钟）</th><th>过关标准</th></tr></thead><tbody><tr><td>1</td><td>01 节、02 节、03 节、04 节</td><td>建立 Go 的世界观，会读写日常代码</td><td><code>exercises/p1_5basics</code> 的 <code>TestSliceGrow</code>（约 20）、<code>exercises/p30</code> 的 <code>TestNilErrorTrap</code> 与 <code>TestMethodSetMatrix</code>（约 25）</td><td>能解释为什么指针类型能赋给接口而值类型不能；能说出 nil 接口陷阱的成因</td></tr><tr><td>2</td><td>05 节、06 节、07 节、08 节</td><td>错误、并发、运行时的范式</td><td><code>exercises/p3conc</code> 的 <code>TestPool</code> 与 <code>TestFirstOrTimeout</code>（约 25）、<code>exercises/p14pipe</code> 的 <code>TestPipeline</code>（约 15）、<code>exercises/p31sched</code> 的 <code>TestWorkerPool</code> 与 <code>TestNilChannelSelect</code>（约 25）</td><td>写出一个带 context 取消和 errgroup 的 pipeline，<code>-race</code> 干净；能解释 goroutine 泄漏怎么出现</td></tr><tr><td>3</td><td>09 节、10 节、11 节、12 节</td><td>泛型取舍，服务分层、DI、HTTP 与数据库（11 节含认证：Session、JWT、长短 token、OAuth2）</td><td><code>exercises/p33gen</code> 的 <code>TestConstraintNotType</code>（约 15）、<code>exercises/p5deep</code> 的 <code>TestProvideInvoke</code> 与 <code>TestGracefulShutdown</code>（约 25）、<code>exercises/p9db</code> 的 <code>TestTxAtomicity</code> 与 <code>TestNullStrategies</code>（约 25）</td><td>能画出 handler、service、repository 的依赖方向，说出每层依赖的是接口还是实现；能说出 JWT 为什么登不掉、长短 token 怎么解决</td></tr><tr><td>4</td><td>13 节、14 节、15 节</td><td>缓存与消息、测试策略（14 节含 TDD 全流程与双写同步位置三选）、可观测</td><td><code>exercises/p21test</code> 的 <code>TestBackoffTable</code> 与 <code>TestRetryVirtualTime</code>（约 25）、<code>exercises/p15slog</code> 的 <code>TestCtxRequestID</code>（约 15）</td><td>能说清缓存穿透、击穿、雪崩各自的对策；会写表驱动加 fake 的测试；能说出双写要在哪一层同步、什么条件下必须同库不同表</td></tr><tr><td>5</td><td>16 节、17 节、18 节</td><td>稳定性与一致性：这是后端工程里最值钱的一块</td><td>读 <code>dnsproxi-go/tcp/server.go</code> 的 <code>MaxInFlight</code> 丢帧限流，对比 <code>main.go</code> 里 worker pool 的阻塞式背压，再改造</td><td>能手写令牌桶与三态熔断的状态转移；能说出 Saga、TCC、outbox 各自的适用场景</td></tr><tr><td>6</td><td>19 节、20 节、21 节</td><td>微服务治理、注册发现、搜索与 Feed 的套路</td><td>无单独练习，重做各节的内存版小例子</td><td>能解释&quot;先模块化再进程化&quot;的拆分顺序；能说出推模型和拉模型的取舍</td></tr><tr><td>7</td><td>22 节、23 节、24 节、25 节</td><td>运行环境，读完 dnsproxi-go，按 minifeed 阶段 1 到 4 读懂一版正确答案</td><td>跑通 <code>dnsproxi-go</code> 的全部测试（本来就是绿的），做完 24 节的第一个改造，对照 25 节的表读 <code>minifeed/</code> 的阶段 1 到 4 骨架</td><td>能不看文档画出 dnsproxi 的请求路径，并指出每个范式在哪个文件；能说出 minifeed 阶段 5（关注与 Feed）你会先写哪张表</td></tr></tbody></table><p>第 1 到 4 天每天 3 到 5 节加约 1 小时练习：第 1 天头部时长 605 分钟，约 10.1 小时（115+35+145+280），01、03、04 节吸收批审内容后变长；第 2 天 240 分钟，约 4.0 小时；第 3 天 240 分钟，约 4.0 小时（11 节吸收了认证、各节吸收了原材料细节后变长）；第 4 天 340 分钟，约 5.7 小时。 第 5 到 7 天读得慢一点是正常的：第 5 天的三节都是&quot;深入&quot;档，165 分钟，约 2.8 小时；第 6 天 145 分钟，约 2.4 小时；第 7 天 22 到 25 节共 115 分钟，约 1.9 小时，是全表最轻的一天，但走读 dnsproxi 与 minifeed 骨架的时间不受头部时长约束，留足半天。七天合计 1850 分钟，约 30.8 小时（见下面&quot;如果时间更紧&quot;的裁法）。</p><p>之后进入项目线，这才是真正的学习：</p><ul><li><strong>dnsproxi-go</strong>（24 节）：把前面的范式在真实代码里找一遍，再做改造。AD 标志与信号关停两题已有实现；现有练习是对照命中路径的缓冲池方案做压测，判断何时值得启用。</li><li><strong>minifeed</strong>（25 节）：按蓝图自己做一个缩小版，每个阶段用测试验收。做这个项目时遇到的每个具体问题，再回头查对应的节和原材料。</li></ul><p>两个说明。练习时间按&quot;删掉实现重写到测试全绿&quot;估算，表里的分钟数是第一次做（读懂参考实现再加自己写）的开销，第二次做可以砍半。第 5 天的练习不是写代码而是读代码：<code>MaxInFlight</code> 在 <code>dnsproxi-go/tcp/server.go</code>，worker pool 背压在 <code>dnsproxi-go/main.go</code>，两者是&quot;丢帧&quot;和&quot;排队&quot;两种过载策略的活例子，读完试着说出 22 节的哪个机制决定了 TCP 版必须丢帧。</p><h3 id="进阶路线的三条经验" tabindex="-1">进阶路线的三条经验 <a class="header-anchor" href="#进阶路线的三条经验" aria-label="Permalink to &quot;进阶路线的三条经验&quot;">​</a></h3><p>七天之后怎么继续走，三个人的进阶自述给出同一套答案（TBX03 从测试转研发的孔令飞、TBX06 游戏公司后端主程罗杰、TBX07 从销售转分布式存储工程师的徐祥曦），叙事细节略，这里只收可操作的结论：</p><ol><li><strong>先定位，再补缺口</strong>。能力大致分五级：初级能读项目代码，中级能独立写完整程序、能做二次开发，高级熟练用 channel、interface、并发并用 OO 思想做项目，资深与专家再往上加编程哲学、生态与架构能力，专家要少依赖搜索、有自己的方法论、能设计高可用可伸缩的应用并领军团队；级别间没有标准边界，当自评坐标用。初中级自学就够：快速通读两本经典基础书（《Go 程序设计语言》《Go 语言编程》），不求记住，先知道知识点有哪些、能用在哪，再写适量小代码段，就具备读项目代码的能力；高级及以上必须靠工作中的真实研发实战，想在 Go 上走远就在合适时机切到研发岗。资深阶段最常见的四个痛点是知识盲区、学不到最佳实践、知识不成体系、缺一线项目练手，作者的解法是大规模调研后自己造脚手架：调研 2000+ 开源项目、5000+ 文章，按最佳实践写出 iam。〔TBX03 p1-2〕〔TBX03 p4-5〕〔TBX03 p8-9〕〔TBX03 p9-10〕</li><li><strong>升级的引擎是需求驱动的实战循环</strong>。没有现成需求就把痛点抽象成需求（人工发版效率低、易出错，那就做一个版本发布系统）；实战精髓是&quot;抄&quot;和&quot;改&quot;：在 GitHub 找优秀项目二次开发，学设计又最快交付，比从零自研更省也更稳；循环是&quot;发现需求、调研开源、二开、团队分享&quot;，期间刻意减少对搜索引擎的依赖，需要时用 channel、interface 和 OO 思想去改造项目。〔TBX03 p5-7〕TBX07 的作者是同款路线：主动问存储团队&quot;你们缺人不？&quot;换来转岗，&quot;当什么都准备好时，往往也就没有机会试一试了&quot;；硬啃纠删码论文（思而不学则殆），看不懂就战略性撤退，借一门化学公开课把有限域补上，两周用 Go 加 Plan9 汇编写出 ISA-L 七成性能的第一版，再换矩阵运算形式追平并开源；更早的一场算法比赛（求 2^64-1 内最大素数，靠刚学的费马小定理和素数定理）让他第一次把想法变成几毫秒的程序。〔TBX07 p3-6〕架构能力走先业务后云原生：先了解当前业务的整体部署方式、手动搭一个小型测试环境、走读核心代码，再手搭 Kubernetes、部署小型微服务系统、配齐日志监控调用链；工作里有架构任务就踊跃参与，以工作驱动最高效。〔TBX03 p10-11〕</li><li><strong>输入必须配输出和复习，问题要先于文档</strong>。听讲与阅读的知识留存率最多 10%，不复习第二天只剩 5%；复习四步：当天细读，次日复习并做笔记，有实战内容就抽时间写代码，一个月内再复习一次。输出三选一：讲给同事、用进日常工作、写博客，教会别人才算真正掌握；零散博客能解恐惧但不成体系，要成体系地学，再读源码上层次；选型别信单点言论，&quot;Go 简单不用框架&quot;把人坑进标准库硬搞，社区主流其实是 gin；Python 完整学过三遍、零实践，至今写不出代码，没有实践的语言学习无效。〔TBX06 p2-7〕架构设计的方法论在 TBX07：先把&quot;设计一套存储系统&quot;转成一个个具体问题，由问题引导出新问题，长成一张有组织的网再落纸面；引路人用&quot;是还是不是&quot;的追问打磨了四个月才允许动手，好问题比先写的文档值钱。〔TBX07 p7-8〕</li></ol><p>省去的：三人的时间线与推荐清单（go-micro 已大版本分裂、二进制手搭 Kubernetes 的教程与现行 kubeadm/kind 做法有代差，只作理念参考）、TBX07 的 Go 贡献礼节（改进集中到一次提交，别刷屏式反复提交）、TBX06 的笔记回顾习惯；叙事细节略，完整叙事在 work/digest 的 TBX03、TBX06、TBX07 三个单元。</p><h2 id="如果时间更紧" tabindex="-1">如果时间更紧 <a class="header-anchor" href="#如果时间更紧" aria-label="Permalink to &quot;如果时间更紧&quot;">​</a></h2><p>只读&quot;深入&quot;档的节：04、05、06、07、10、13、14、16、17、18、19，头部时长相加是 725 分钟，约 12.1 小时；这是手册的主干，其余节需要时再查。更狠的裁法：主干里再只留 06、10、13、16，头部时长合计 265 分钟，约 4.4 小时，配合 24 节的项目走读，够应付&quot;快速接手一个 Go 服务&quot;的场景。 时间更紧时的读法也要变：跳过每节的示例运行，只读正文和&quot;小结&quot;，判断题用来抽查理解。代价记在心里：这一版手册的可运行示例是理解成本最低的部分，跳过它们等于退回旧版浓缩笔记的读法。</p><p>反过来，时间充裕时可以完成 24 节的命中路径压测练习，或者按 25 节的阶段表做 minifeed 的阶段 5；结合具体问题再回查相关章节。</p><h2 id="如果想按主题而不是按顺序读" tabindex="-1">如果想按主题而不是按顺序读 <a class="header-anchor" href="#如果想按主题而不是按顺序读" aria-label="Permalink to &quot;如果想按主题而不是按顺序读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想解决的问题</th><th>先读</th></tr></thead><tbody><tr><td>一个接口怎么设计才好测、好换</td><td>04、10、14</td></tr><tr><td>一个服务怎么扛住流量高峰</td><td>13、16，练习对照 <code>dnsproxi-go/guard/</code> 的令牌桶与熔断</td></tr><tr><td>数据怎么搬、怎么保持一致</td><td>17、18</td></tr><tr><td>服务多了怎么管</td><td>19、20、23</td></tr><tr><td>程序怎么交付到机器上跑</td><td>22、23，练习对照 <code>labs/compose/</code> 的三服务编排</td></tr><tr><td>怎么读别人的 Go 项目</td><td>02、24，以及旧章 <code>notes/p4-ejdb.md</code>、<code>notes/p5-deepsearch.md</code></td></tr><tr><td>面试前突击</td><td>16、13、19，加上 WX-sms 的短信服务话术</td></tr><tr><td>评审被问&quot;为什么不用 X&quot;</td><td>27 节场景决策对照，判据都在&quot;先问&quot;后面</td></tr></tbody></table><p>最后借课程总结一页，收拢贯穿全书的三条工程原则：接口为预期中的变化而定义，知道哪里会变但不知道怎么变时，只按当下需求做最简单的抽象，别指望设计一个用十年的接口；超前设计不超前实现，异步优先但先保证正确；微服务、DDD、最佳实践都是工具不是目标，走投无路再上微服务，别盲从&quot;最佳实践&quot;。〔W21-1 p3〕〔W21-1 p9〕</p><h2 id="手册之外还有什么" tabindex="-1">手册之外还有什么 <a class="header-anchor" href="#手册之外还有什么" aria-label="Permalink to &quot;手册之外还有什么&quot;">​</a></h2><ul><li>旧长版 <code>notes/</code> 详细完整，适合当参考手册；<code>work/digest/</code> 是原材料每个单元的知识点摘要（带页码），用来判断某一讲值不值得读。</li><li>原材料在本地、不入库（Tony Bai 的 52 讲、21 周项目课、<code>go_basic</code> 等代码包），各节末尾的页码指向它们。</li></ul>',24)])])}const q=e(c,[["render",a]]);export{h as __pageData,q as default};
